# Regenerates every public page and js/search-index.js. Run: python3 build/build.py
import os,json,sys
sys.path.insert(0,os.path.dirname(os.path.abspath(__file__)))
from format_html import pretty
def save(p,t):
    open(p,'w',encoding='utf-8').write(pretty(t) if p.endswith('.html') else t)
R=os.path.join(os.path.dirname(os.path.abspath(__file__)),'..')
G=[('What We Offer',[('energy-monitoring','Energy Monitoring','See how much electricity your home or business uses, broken down by appliance or area.'),('usage-analytics','Usage Analytics','Compare daily, weekly and monthly use to find your peak times.'),('high-usage-alerts','High-Usage Alerts','Set a power limit and get warned when your usage goes above it.'),('energy-saving-goals','Energy-Saving Goals','Set a monthly target and track your progress.')]),
('For Homes',[('household-monitoring','Household Energy Monitoring','Understand which appliances drive your household electricity use.'),('track-usage','Track Electricity Usage','Follow your usage through the day, week and month.'),('reduce-bills','Reduce Energy Bills','Find the habits and appliances that cost you the most, then change them.'),('home-tips','Home Energy-Saving Tips','Simple changes that cut waste around the house.')]),
('For Business',[('business-monitoring','Business Energy Monitoring','Monitor energy use across a shop, office or site.'),('energy-performance','Energy Performance','Measure how efficiently your business uses energy over time.'),('business-analytics','Business Usage Analytics','Compare usage by period, area or equipment to spot waste.'),('efficiency-solutions','Energy Efficiency Solutions','Practical ways for businesses to reduce consumption and costs.')]),
('Energy Lab',[('understanding-energy','Understanding Energy','Plain-language explanations of watts, kilowatt-hours and your bill.'),('appliance-guide','Appliance Energy Guide','How much power common household appliances typically use.'),('energy-calculator','Energy Calculator','Estimate what an appliance costs to run.'),('sustainability-insights','Sustainability Insights','How using less electricity helps reduce carbon emissions.')]),
('Resources',[('blog','Blog','News and ideas on using energy wisely.'),('events','Events','Workshops and talks about energy and sustainability.'),('saving-guides','Energy-Saving Guides','Step-by-step guides for lowering your usage.'),('faq','Frequently Asked Questions','Answers to common questions about the platform.')]),
('About',[('about-project','About Our Project','Why we are building the EcoWatt and who is behind it.'),('our-mission','Our Mission','Helping people understand and reduce their electricity use.'),('contact','Contact Us','How to get in touch with the project team.')])]
CH='<svg class="chev" width="12" height="12" viewBox="0 0 12 12" aria-hidden="true"><path d="M2 4l4 4 4-4" fill="none" stroke="currentColor" stroke-width="1.8"/></svg>'
SV='<svg width="20" height="20" viewBox="0 0 20 20" aria-hidden="true"><circle cx="8.5" cy="8.5" r="5.5" fill="none" stroke="currentColor" stroke-width="2"/><path d="M13 13l5 5" stroke="currentColor" stroke-width="2"/></svg>'
def nav(cur):
    h='<li><a href="index.html"%s>Home</a></li>'%(' aria-current="page"' if cur=='index' else '')
    for i,(g,its) in enumerate(G):
        ls=''.join('<li><a href="%s.html"%s>%s</a></li>'%(s,' aria-current="page"' if s==cur else '',t) for s,t,d in its)
        h+='<li class="dd"><button class="nb" aria-expanded="false" aria-controls="dd%d">%s%s</button><ul class="dm" id="dd%d">%s</ul></li>'%(i,g,CH,i,ls)
    sb='<button class="sbtn" aria-label="Search" aria-expanded="false" aria-controls="sp">%s</button>'%SV
    return ('<header class="site"><div class="bar"><a class="brand" href="index.html"><img src="images/logo.svg" alt="EcoWatt logo" width="44" height="44"><span>EcoWatt</span></a>'+sb.replace('class="sbtn"','class="sbtn m"')+
    '<button class="burger" id="burger" aria-label="Menu" aria-expanded="false" aria-controls="menu">&#9776;</button>'
    '<nav id="menu" aria-label="Main"><ul class="main">'+h+'</ul><div class="macts">'+sb+'<a class="lnk" href="login.html">Log In</a><a class="gold" href="register.html">Get Started</a></div></nav></div>'
    '<div class="sp" id="sp" hidden><div class="w"><form id="sf" role="search"><input id="q" type="search" placeholder="Search articles, guides and pages..." aria-label="Search public pages" autocomplete="off"><button class="btn" type="submit">Search</button><button class="btn o" type="button" id="sx" aria-label="Close search">Clear</button></form><ul id="sr" aria-live="polite"></ul><p class="mu" style="font-size:.85rem;margin:10px 0 0">Searches the public pages of this prototype only.</p></div></div></header>')
def foot():
    c=lambda i:'<ul>'+''.join('<li><a href="%s.html">%s</a></li>'%(s,t) for s,t,d in G[i][1])+'</ul>'
    return ('<footer><div class="w"><div class="fg"><div><h3>EcoWatt</h3><p>Understand, monitor and reduce your electricity use.</p><p>Email: [email placeholder]<br>Phone: [phone placeholder]<br>Address: [address placeholder]</p></div>'
    '<div><h3>What We Offer</h3>'+c(0)+'</div><div><h3>For Homes</h3>'+c(1)+'</div><div><h3>For Business</h3>'+c(2)+'</div><div><h3>Learn</h3><ul><li><a href="understanding-energy.html">Energy Lab</a></li><li><a href="blog.html">Blog</a></li><li><a href="faq.html">FAQ</a></li><li><a href="contact.html">Contact Us</a></li><li><a href="login.html">Log In</a></li><li><a href="register.html">Get Started</a></li></ul></div></div>'
    '<div class="fb">EcoWatt, a PROF709 Capstone A prototype by Dipa Yam, Elvish Shishir and Pratik Saphal. Demonstration data is simulated.</div></div></footer>')
def shell(title,body,cur,scripts=''):
    return ('<!doctype html><html lang="en"><head><meta charset="utf-8"><title>%s | EcoWatt</title><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="EcoWatt: understand and reduce electricity use at home and in business."><link rel="stylesheet" href="css/site.css"></head><body>'%title+nav(cur)+body+foot()+'<script src="js/search-index.js"></script><script src="js/nav.js"></script>'+scripts+'</body></html>')
CTA='<section class="band"><div class="w"><h2>Ready to understand your energy use?</h2><p>Create an account to get started.</p><a class="gold" href="register.html">Get Started</a></div></section>'
EXTRA={'energy-calculator':'<form class="form" id="calc"><label>Appliance power (watts)<input type="number" name="w" value="1500" min="1" required></label><label>Hours used per day<input type="number" name="h" value="2" min="0" step="0.1" required></label><label>Price per kWh in dollars (placeholder rate)<input type="number" name="r" value="0.32" min="0" step="0.01" required></label><button class="btn" type="submit">Calculate</button><p id="co" role="status" style="margin-top:14px;font-weight:600"></p></form>',
'faq':'<details><summary>Is real smart-meter data connected?</summary><p>Not yet. This prototype uses simulated data for demonstration.</p></details><details><summary>Do I need an account?</summary><p>You can browse the public pages freely. The account area is for logged-in users.</p></details><details><summary>Who is it for?</summary><p>Households and businesses that want to understand and reduce their electricity use.</p></details><details><summary>Is my data safe?</summary><p>No personal data is collected in this prototype. Secure accounts will be built in a later stage.</p></details>',
'contact':'<div class="card" style="max-width:460px"><p>Email: [email placeholder]<br>Phone: [phone placeholder]<br>Address: [address placeholder]</p><p class="mu">A contact form will be added in a later stage.</p></div>'}
idx=[{'u':'index.html','t':'Home','s':'Home','d':'EcoWatt for households and businesses.','k':'home energy monitor'}]
for g,its in G:
    for s,t,d in its:
        idx.append({'u':s+'.html','t':t,'s':g,'d':d,'k':(s.replace('-',' ')+' '+g+' '+d).lower()})
        rel=''.join('<li><a href="%s.html">%s</a></li>'%(a,b) for a,b,c in its if a!=s)
        body='<main><section class="ph"><div class="w"><p class="crumb">%s</p><h1>%s</h1><p class="lead">%s</p>%s<p class="note">This page is a placeholder in the Capstone A prototype. Full content will be added in a later stage.</p><h2>More in %s</h2><ul class="rel">%s</ul></div></section>%s</main>'%(g,t,d,EXTRA.get(s,''),g,rel,CTA)
        save(os.path.join(R,s+'.html'),shell(t,body,s,'<script src="js/forms.js"></script>' if s=='energy-calculator' else ''))
for s,t,d in [('login','Log In','Sign in to your account area.'),('register','Get Started','Create an account for your home or business.')]:
    idx.append({'u':s+'.html','t':t,'s':'Account','d':d,'k':s+' sign in account register'})
if True:
    L='<form class="form" id="lf"><label>Email<input type="email" required autocomplete="email"></label><label>Password<input type="password" required autocomplete="current-password"></label><button class="btn" type="submit">Log In</button><p id="fm" role="status"></p></form><p>New here? <a href="register.html">Get Started</a></p><div class="note"><b>Prototype preview.</b> Real sign-in needs a backend that does not exist yet. You can preview the account area with simulated data, without a password.<br><br><button class="btn o" id="demo" type="button">Preview the account area (demo)</button></div>'
    Rg='<form class="form" id="rf"><label>Full name<input type="text" required autocomplete="name"></label><label>Email<input type="email" required autocomplete="email"></label><label>Password<input type="password" required minlength="8" autocomplete="new-password"></label><fieldset><legend>I am signing up as</legend><label><input type="radio" name="t" checked> A household</label><label><input type="radio" name="t"> A business</label></fieldset><button class="gold" type="submit">Create account</button><p id="fm" role="status"></p></form><p>Already have an account? <a href="login.html">Log In</a></p><p class="note">Registration is a design preview. Nothing is sent or stored until a backend is built.</p>'
    for s,t,b in [('login','Log in to your account',L),('register','Get started with EcoWatt',Rg)]:
        save(os.path.join(R,s+'.html'),shell(dict(login='Log In',register='Get Started')[s],'<main><section class="ph"><div class="w"><h1>%s</h1>%s</div></section></main>'%(t,b),s,'<script src="js/forms.js"></script>'))
A=lambda s:'<a class="t" href="%s.html">'%s
home=('<main><section class="hero"><div class="w"><h1>Smarter energy management for homes and businesses</h1><p class="lead">EcoWatt helps you understand how much electricity you use, spot waste and work towards using less.</p><div class="acts"><a class="gold" href="household-monitoring.html">Explore for Homes</a><a class="btn o" href="business-monitoring.html">Explore for Business</a></div></div></section>'
'<section class="sec alt"><div class="w"><h2>Why use the monitor</h2><div class="cards"><div class="card"><h3>See the full picture</h3><p>Understand when and where your electricity goes.</p></div><div class="card"><h3>Cut waste</h3><p>Spot high-usage habits and appliances early.</p></div><div class="card"><h3>Stay in control</h3><p>Set limits and goals that suit your home or business.</p></div><div class="card"><h3>Reduce your footprint</h3><p>Using less electricity helps lower emissions.</p></div></div></div></section>'
'<section class="sec"><div class="w"><h2>What you can do with an account</h2><p class="mu">A preview of the features in the private account area. Your account is where usage data lives.</p><div class="cards">'
+''.join('<div class="card"><h3>%s%s</a></h3><p>%s</p></div>'%(A(s),t,d) for s,t,d in G[0][1])+'</div></div></section>'
'<section class="sec alt"><div class="w"><h2>Learn how to use less</h2><div class="cards"><div class="card"><h3>%sHome energy-saving tips</a></h3><p>Simple changes around the house.</p></div><div class="card"><h3>%sEnergy-saving guides</a></h3><p>Step-by-step ways to lower usage.</p></div><div class="card"><h3>%sBlog</a></h3><p>News and ideas on using energy wisely.</p></div></div></div></section>'%(A('home-tips'),A('saving-guides'),A('blog'))+CTA+'</main>')
save(os.path.join(R,'index.html'),shell('Home',home,'index'))
save(os.path.join(R,'js','search-index.js'),'const SEARCH = '+json.dumps(idx,indent=2)+';')
print(len(idx),'searchable pages built')
